    return Response.json({units:units.map(u=>({id:u.id,name:u.name,formulas:diagnostic(state,u.id).length})),rows:diagnostic(state,unitId,{from:query.get('from')??'',to:query.get('to')??'',...query.has('group')?{group:query.get('group')}:{} })});
